<?php
declare(strict_types=1);namespace App\Infrastructure\Extraction;use App\Application\QuestionBank\Port\QuestionPdfAssetExtractorInterface;final class PdfimagesQuestionPdfAssetExtractor implements QuestionPdfAssetExtractorInterface{public function __construct(private readonly string $directory='/app/storage/question-pdf-assets'){}public function extract(string $pdf,string $hash):array{$dir=$this->directory.'/'.$hash;if(!is_dir($dir))mkdir($dir,0755,true);$list=shell_exec('pdfimages -list '.escapeshellarg($pdf))??'';$pages=[];foreach(explode("\n",$list)as $line)if(preg_match('/^\s*(\d+)\s+(\d+)\s+image\s+(\d+)\s+(\d+)/',$line,$m)&&((int)$m[3])>30&&((int)$m[4])>30)$pages[(int)$m[1]][]=(int)$m[2];chmod($dir,0755);$prefix=$dir.'/image';if(!glob($prefix.'-*'))shell_exec('pdfimages -png '.escapeshellarg($pdf).' '.escapeshellarg($prefix));$result=[];foreach($pages as $page=>$numbers)foreach($numbers as $number){$path=sprintf('%s-%03d.png',$prefix,$number);if(is_file($path)&&filesize($path)>1024)$result[$page][]=$path;}return$result;}}